specs=[('two real modes',{}),('prepared hidden offset',dict(yNumerator=1)),('initially quasisteady',dict(yNumerator=2,yDenominator=3)),('epsilon half',dict(epsilonDenominator=2)),('epsilon sixteenth',dict(epsilonDenominator=16)),('epsilon thousandth',dict(epsilonDenominator=1000)),('stiff hidden layer',dict(epsilonDenominator=1000000000,yNumerator=1,dNumerator=8)),('resolved initial layer',dict(epsilonDenominator=1000000000,yNumerator=1,dNumerator=8,timeNumerator=1,timeDenominator=1000000000)),('no feedback to observation',dict(bNumerator=0,yNumerator=2)),('no return to hidden',dict(cNumerator=0,yNumerator=2)),('uncoupled',dict(bNumerator=0,cNumerator=0,yNumerator=1)),('Jordan forced observation',dict(aNumerator=1,dNumerator=1,cNumerator=0,xNumerator=0,yNumerator=1)),('scalar decay',dict(aNumerator=1,dNumerator=1,bNumerator=0,cNumerator=0,yNumerator=1)),('damped oscillation',dict(aNumerator=1,dNumerator=1,bNumerator=2,cNumerator=-2)),('fast oscillation',dict(aNumerator=1,aDenominator=1000000000,dNumerator=1,dDenominator=1000000000,bNumerator=8,cNumerator=-8,epsilonDenominator=1000000000)),('negative observation',dict(xNumerator=-1,yNumerator=1)),('negative couplings',dict(bNumerator=-1,cNumerator=-2,yNumerator=-1)),('marginal stationary',dict(aNumerator=1,bNumerator=1,cNumerator=1,dNumerator=1,xNumerator=1,yNumerator=1)),('marginal transient',dict(aNumerator=1,bNumerator=1,cNumerator=1,dNumerator=1)),('zero initial state',dict(xNumerator=0)),('zero time',dict(yNumerator=1,timeNumerator=0)),('dense records',dict(sampleSteps=64)),('small physical time',dict(timeNumerator=1,timeDenominator=1000000000)),('near coalescence real',dict(aNumerator=1,dNumerator=1,bNumerator=1,bDenominator=1000000000,cNumerator=1,cDenominator=1000000000)),('near coalescence oscillatory',dict(aNumerator=1,dNumerator=1,bNumerator=1,bDenominator=1000000000,cNumerator=-1,cDenominator=1000000000)),('real series boundary',dict(aNumerator=1,dNumerator=1,bNumerator=1,bDenominator=2,cNumerator=1,cDenominator=2,timeNumerator=1,timeDenominator=2)),('real beyond series boundary',dict(aNumerator=1,dNumerator=1,bNumerator=1,bDenominator=2,cNumerator=1,cDenominator=2,timeNumerator=500000001,timeDenominator=1000000000)),('rotation series boundary',dict(aNumerator=1,dNumerator=1,bNumerator=1,bDenominator=2,cNumerator=-1,cDenominator=2,timeNumerator=1,timeDenominator=2)),('rotation beyond series boundary',dict(aNumerator=1,dNumerator=1,bNumerator=1,bDenominator=2,cNumerator=-1,cDenominator=2,timeNumerator=500000001,timeDenominator=1000000000)),('large hidden gain',dict(aNumerator=8,dNumerator=1,dDenominator=1000000000,bNumerator=1,bDenominator=1000000000,cNumerator=8,epsilonDenominator=1000000000)),('slow hidden relaxation',dict(aNumerator=1,dNumerator=1,dDenominator=1000000000,bNumerator=1,bDenominator=1000000000,cNumerator=0,yNumerator=1)),('rational coefficients',dict(aNumerator=7,aDenominator=3,bNumerator=-2,bDenominator=3,cNumerator=5,cDenominator=7,dNumerator=9,dDenominator=4,epsilonNumerator=2,epsilonDenominator=7,xNumerator=3,xDenominator=2,yNumerator=-4,yDenominator=3,timeNumerator=5,timeDenominator=3)),('maximum epsilon',dict(aNumerator=8,bNumerator=8,cNumerator=8,dNumerator=8,epsilonNumerator=4)),('equivalent fractions',dict(aNumerator=4,aDenominator=2,bNumerator=2,bDenominator=2,cNumerator=4,cDenominator=2,dNumerator=6,dDenominator=2)),('tiny positive coupling product',dict(bNumerator=1,bDenominator=1000000000,cNumerator=1,cDenominator=1000000000)),('negative hidden offset',dict(yNumerator=-1))]
