def mpf(x):return mp.mpf(x.numerator)/x.denominator
def text(x):return mp.nstr(x,170)
cases=[]
for label,patch in specs:
 p={**base,**patch};q=lambda s:F(p[s+'Numerator'],p[s+'Denominator']);a,b,c,d,eps,x0,y0,T=[q(s)for s in ['a','b','c','d','epsilon','x','y','time']];A,B,C,D,E,X,Y,TT=map(mpf,[a,b,c,d,eps,x0,y0,T]);k=D/E;mu=-A+B*C/D
 # Third component J solves JDot=x-kJ independently of the memory reconstruction.
 G=mp.matrix([[-A,B,0],[C/E,-k,0],[1,0,-k]]);initial=mp.matrix([X,Y,0]);rows=[]
 for i in range(p['sampleSteps']+1):
  t=TT*i/p['sampleSteps'];flow=mp.expm(G*t);state=flow*initial;x,y,J=state;decay=mp.exp(-k*t);force=B*Y*decay;memory=B*C/E*J;xm=X*mp.exp(mu*t);ym=C/D*xm;instant=-A*x;direct=instant+B*y;mismatch=y-C/D*x
  row=dict(time=str(T*F(i,p['sampleSteps'])),x=text(x),y=text(y),markovX=text(xm),quasiSteadyHidden=text(ym),observedError=text(x-xm),hiddenError=text(y-ym),instantaneousTerm=text(instant),initialHiddenTerm=text(force),homogeneousHidden=text(Y*decay),initialHiddenLogAbsolute=text(mp.log(abs(B*Y))-k*t)if B*Y else None,convolutionOfObservedState=text(J)if B*C else None,memoryIntegral=text(memory),memoryKernelAtLag=text(B*C/E*decay),directObservedDerivative=text(direct),reconstructedObservedDerivative=text(instant+force+memory),memoryEquationResidual='0',quasiSteadyMismatch=text(mismatch),markovLocalDefect=text(B*mismatch),markovDefectResidual='0',hiddenReconstructionResidual='0'if B*C else None,flowMatrix=[[text(flow[i,j])for j in range(2)]for i in range(2)])
  rows.append(row)
 cases.append(dict(label=label,input=p,expected=dict(history=rows)))
parser=argparse.ArgumentParser();parser.add_argument('--output',required=True);args=parser.parse_args();path=Path(args.output);path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps({'provenance':'mpmath220-digit augmented3x3 matrix exponential with an independently integrated convolution state JDot=x-(d/epsilon)J. No production imports, eigenvector formulas, coalescence series or source reconstruction residuals.170-digit reference rounding.','cases':cases},indent=2)+'\n');print(json.dumps({'preparations':len(cases),'records':sum(len(c['expected']['history'])for c in cases)}))
